#include "timing_metadata.hpp"
#include "daxa_refinement_common.hpp"
#include <stereoforge/daxa_dual_preprocess.hpp>
#include <cstring>
using namespace refinement_app;
template<class T> static void exact_plane(const std::vector<T>& a,const std::vector<T>& b){check(a.size()==b.size()&&(a.empty()||std::memcmp(a.data(),b.data(),a.size()*sizeof(T))==0),"raw reuse differs from direct refinement");}
static void exact_readback(const DaxaRefinementReadback& a,const DaxaRefinementReadback& b){
#define EQ(n) exact_plane(a.n,b.n)
 EQ(disparity);EQ(confidence);EQ(validity);EQ(depth);EQ(metric_confidence);EQ(metric_validity);EQ(provenance);EQ(source_ids);EQ(age_ns);EQ(prediction);EQ(prediction_validity);EQ(lower);EQ(upper);EQ(reason);EQ(method);EQ(winner);EQ(best_cost);EQ(second_cost);EQ(supported_candidates);EQ(evaluated_candidates);EQ(subpixel_applied);EQ(raw_disparity);EQ(raw_confidence);EQ(raw_validity);EQ(census);EQ(census_validity);EQ(luma);EQ(support);for(unsigned eye=0;eye<2;++eye)exact_plane(a.rectified_rgb[eye],b.rectified_rgb[eye]);
#undef EQ
}
int main(int argc,char**argv){try{
 Options options(argc,argv);Prepared prepared(options);auto frames=options.number_or("--frames",100),warmup=options.number_or("--warmup",20);check(frames>=1&&frames<=300&&warmup<=30,"invalid frame counts");auto variant=options.values.contains("--variant")?options.values.at("--variant"):"dual";check(variant=="dual"||variant=="separate","variant must be dual or separate");check(prepared.refinement.slots==2,"dual benchmark requires exactly two slots");prepared.refinement.borrow_full_frame=true;
 auto ctx=std::make_shared<DaxaFoundation>(options.validation);json result;{DaxaDepthPipeline olddepth(prepared.coarse.rectification,prepared.depth,ctx,prepared.source);DaxaPreprocess oldfull(prepared.target.rectification,2,ctx);DaxaDualPreprocess dual(prepared.target.rectification,prepared.coarse.rectification,2,ctx);
 auto oldc=olddepth.enqueue(prepared.source);auto oldf=oldfull.enqueue(prepared.source);auto pair=dual.enqueue(prepared.source);DaxaDepthPipeline newdepth(prepared.depth,ctx,pair.coarse);auto newc=newdepth.enqueue_preprocessed(pair.coarse);DaxaRefinement oldref(ctx,oldc,oldf,prepared.refinement),newref(ctx,newc,pair.full,prepared.refinement);oldc.wait();oldf.wait();newc.wait();oldc={};oldf={};newc={};pair={};olddepth.collect();oldfull.collect_completed_sources();newdepth.collect();dual.collect();
 std::vector<double> wall,enqueue,wait;wall.reserve(frames);enqueue.reserve(frames);wait.reserve(frames);DaxaRefinement::Frame output;DaxaDepthPipeline::Frame coarse;DaxaFrame full;DaxaDualPreprocess::Frame live;
 for(unsigned i=0;i<frames+warmup;++i){auto a=Clock::now();output={};coarse={};full={};live={};if(variant=="dual"){newref.collect();newdepth.collect();dual.collect();}else{oldref.collect();olddepth.collect();oldfull.collect_completed_sources();}if(variant=="dual"){live=dual.enqueue(prepared.source);coarse=newdepth.enqueue_preprocessed(live.coarse);output=newref.process(coarse,live.full);}else{coarse=olddepth.enqueue(prepared.source);full=oldfull.enqueue(prepared.source);output=oldref.process(coarse,full);}auto b=Clock::now();output.wait();auto c=Clock::now();if(i>=warmup){enqueue.push_back(std::chrono::duration<double,std::milli>(b-a).count());wait.push_back(std::chrono::duration<double,std::milli>(c-b).count());wall.push_back(std::chrono::duration<double,std::milli>(c-a).count());}}
 output={};coarse={};full={};live={};oldref.collect();newref.collect();olddepth.collect();oldfull.collect_completed_sources();newdepth.collect();dual.collect();oldc=olddepth.enqueue(prepared.source);oldf=oldfull.enqueue(prepared.source);pair=dual.enqueue(prepared.source);newc=newdepth.enqueue_preprocessed(pair.coarse);auto oldout=oldref.process(oldc,oldf);auto newout=newref.process(newc,pair.full);exact_readback(oldref.readback(oldout),newref.readback(newout));
 result=prepared.report();result["schema"]="stereoforge.daxa_dual_preprocess_benchmark.v1";result["coarse_right_reference_mode"]="independent_sgm";result["variant"]=variant;result["frames"]=frames;result["warmup"]=warmup;result["validation_requested"]=options.validation;result["device"]=json::parse(ctx->report());result["all_30_planes_exact_between_variants"]=true;result["gpu_upload_to_metric_ms"]=nullptr;result["gpu_timing_scope"]="unavailable: host wall is not GPU time";result["dual_requested_buffer_bytes"]=nullptr;result["memory_scope"]="both configurations allocated; dual producer requested bytes unavailable; device memory not measured";result["measurement_scope"]="serialized same retained source; host wall from resource collection through final refinement wait; excludes capture, RGB-D view and output transport";result["raw_samples_ms"]["host_wall_ms"]=wall;result["raw_samples_ms"]["enqueue_cpu_ms"]=enqueue;result["raw_samples_ms"]["wait_cpu_ms"]=wait;result["host_wall_ms"]=summary(wall);result["enqueue_cpu_ms"]=summary(enqueue);result["wait_cpu_ms"]=summary(wait);result["source_frame_id"]=prepared.source->frame_id;};ctx->close();check(!ctx->validation_errors&&!ctx->validation_warnings,"validation through teardown failed");result["validation_errors_after_teardown"]=ctx->validation_errors.load();result["validation_warnings_after_teardown"]=ctx->validation_warnings.load();prepared.verify(options);auto bytes=result.dump(2)+'\n';write(options.values.at("--output"),bytes.data(),bytes.size());return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
